import React, { useEffect, useMemo, useState } from 'react';
import {
  Activity, Award, BadgeCheck, CalendarDays, ChevronLeft, ChevronRight, CircleAlert, Clock3, FileCheck2,
  Fingerprint, Gavel, LayoutDashboard, ListChecks, LockKeyhole, Network, Plus, QrCode, RadioTower, FileUp,
  ArrowRight, Search, Settings2, ShieldCheck, Sparkles, Trash2, UsersRound
} from 'lucide-react';
import { useAppStore } from '../../lib/store';
import { getCompetitionPolicy } from '../../lib/competition-config';
import { Category, Competition, CompetitionPolicy, RegistrationFieldDefinition } from '../../types';
import { Button } from '../design-system/Button';
import { Ratio } from '../design-system/Ratio';
import { Badge } from '../design-system/Badge';
import { EnterpriseWorkspace } from './EnterpriseWorkspace';
import { uiToken, localizedCountry, automationLevelLabel } from '../../lib/ui-language';
import { ContinuityRecovery } from '../operations/ContinuityRecovery';
import { RealQRCode } from '../design-system/RealQRCode';
import { TRANSITION_PHRASES_AR, TRANSITION_PHRASES_EN } from '../../lib/judging-integrity';
import { deleteCompetitionLogo, isManagedBrandLogoUrl, uploadCompetitionLogo } from '../../lib/brand-assets';

const isAr=(language:string)=>language==='ar';
type MainView='overview'|'design'|'participants'|'operations'|'results'|'enterprise';
type PolicySection='identity'|'registration'|'workflow'|'operations'|'questions'|'judging'|'appeals'|'results'|'certificate'|'privacy';

type Store=ReturnType<typeof useAppStore>;

export const CompetitionOverview: React.FC = () => {
 const store=useAppStore(); const {competition,participants,committees,reviewCases,results,certificates,auditLogs,appeals,language}=store; const ar=isAr(language);
 const policy=getCompetitionPolicy(competition); const readiness=store.getCompetitionReadiness();
 const [view,setView]=useState<MainView>('overview'); const [section,setSection]=useState<PolicySection>('identity'); const [query,setQuery]=useState(''); const [simCount,setSimCount]=useState(Math.max(1,committees.length));
 useEffect(()=>{const open=()=>setView('design');window.addEventListener('mizan:open-competition-dna',open as EventListener);return()=>window.removeEventListener('mizan:open-competition-dna',open as EventListener)},[]);
 const sim=useMemo(()=>store.runSimulation(simCount,30),[simCount,participants.length,committees.length,competition.ruleSet.questionDurationMinutes]);
 const filtered=participants.filter(p=>`${p.code} ${p.fullName} ${p.fullNameArabic} ${localizedCountry(p.country,ar)}`.toLowerCase().includes(query.toLowerCase()));
 const attention=[...readiness.map(i=>({id:i.id,title:ar?i.ar:i.en,kind:'setup'})),...reviewCases.filter(r=>r.status==='pending').slice(0,3).map(r=>({id:r.id,title:ar?`مراجعة ${r.participantCode}`:`Review ${r.participantCode}`,kind:'review'})),...store.incidents.filter(i=>i.status!=='resolved').slice(0,2).map(i=>({id:i.id,title:i.title,kind:'incident'}))];
 const patchPolicy=(mutate:(p:CompetitionPolicy)=>void)=>store.updateCompetitionPolicy(p=>{mutate(p);return p});
 const orgManager=store.currentUser.role==='org_admin'; const leaveCompetition=()=>{window.location.hash='';};
 const nav=[{id:'overview' as const,icon:LayoutDashboard,ar:'اليوم',en:'Overview'},{id:'design' as const,icon:Settings2,ar:'DNA المسابقة',en:'Competition DNA'},{id:'participants' as const,icon:UsersRound,ar:'المشاركون',en:'Participants'},{id:'operations' as const,icon:RadioTower,ar:'التشغيل',en:'Operations'},{id:'results' as const,icon:Award,ar:'النتائج',en:'Results'},{id:'enterprise' as const,icon:ShieldCheck,ar:'المؤسسة',en:'Enterprise'}];
 return <div className="max-w-[1500px] mx-auto px-4 sm:px-6 py-5 sm:py-7"><div className="flex gap-6">
  <aside className="hidden lg:block w-52 shrink-0 pt-1"><div className="sticky top-24 space-y-1"><div className="px-3 mb-4"><div className="text-[10px] font-black tracking-[.16em] text-[#666a67]">{competition.edition}</div><div className="mt-1 text-sm font-extrabold text-[#303733] line-clamp-2">{ar?competition.nameArabic:competition.name}</div></div>{nav.map(n=><NavButton key={n.id} active={view===n.id} onClick={()=>setView(n.id)} icon={n.icon} label={ar?n.ar:n.en}/>)}</div></aside>
  <main className="min-w-0 flex-1">
   {orgManager&&<div className="mb-4"><Button size="sm" variant="ghost" onClick={leaveCompetition} icon={<ArrowRight className="w-4 h-4"/>}>{ar?'العودة إلى مسابقات الجهة':'Back to organization competitions'}</Button></div>}
   <div className="lg:hidden flex gap-1 overflow-x-auto pb-4 mb-4 border-b border-[#dfded7]">{nav.map(n=><button key={n.id} onClick={()=>setView(n.id)} className={`shrink-0 flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold ${view===n.id?'bg-[#214C40] text-white':'bg-white border border-[#dfded7] text-[#626a65]'}`}><n.icon className="w-4 h-4"/>{ar?n.ar:n.en}</button>)}</div>
   {view==='overview'&&<Overview store={store} ar={ar} attention={attention} readiness={readiness} onConfigure={()=>setView('design')}/>} 
   {view==='design'&&<CompetitionDNA store={store} ar={ar} policy={policy} section={section} setSection={setSection} patchPolicy={patchPolicy}/>} 
   {view==='participants'&&<ParticipantsView store={store} ar={ar} query={query} setQuery={setQuery} filtered={filtered}/>} 
   {view==='operations'&&<OperationsView store={store} ar={ar} sim={sim} simCount={simCount} setSimCount={setSimCount} attention={attention}/>} 
   {view==='results'&&<ResultsView store={store} ar={ar}/>} 
   {view==='enterprise'&&<EnterpriseWorkspace/>} 
  </main>
 </div></div>;
};

const Overview=({store,ar,attention,readiness,onConfigure}:{store:Store;ar:boolean;attention:any[];readiness:any[];onConfigure:()=>void})=>{
 const {competition,participants,committees,sealApprovals}=store; const canPublish=['draft','configured'].includes(competition.status); const [publishIssues,setPublishIssues]=useState<string[]>([]); const [publishSuccess,setPublishSuccess]=useState(false);
 const publish=()=>{setPublishSuccess(false);try{const out=store.publishCompetition();if(out.ok){setPublishIssues([]);setPublishSuccess(true)}else setPublishIssues(out.issues||[ar?'تعذر فتح التسجيل.':'Could not open registration.'])}catch{setPublishIssues([ar?'تعذر فتح التسجيل. أعد المحاولة بعد التحقق من الاتصال.':'Could not open registration. Check the connection and try again.'])}};
 return <div className="space-y-5">
  <section className="mizan-surface p-6 sm:p-8"><div className="flex flex-col md:flex-row md:items-end justify-between gap-5"><div><div className="flex flex-wrap items-center gap-2"><Badge>{uiToken(competition.status,ar)}</Badge><Badge variant="neutral" dot={false}>{uiToken(competition.automationLevel,ar)}</Badge></div><h1 className="mizan-title text-3xl sm:text-4xl font-black mt-3">{ar?competition.nameArabic:competition.name}</h1><p className="mizan-muted text-sm mt-2">{competition.venueName||'—'} · {competition.startDate||'—'}</p></div><div className="flex gap-2"><Button onClick={onConfigure} variant="outline" icon={<Settings2 className="w-4 h-4"/>}>{ar?'ضبط':'Configure'}</Button>{canPublish&&<Button onClick={publish} icon={<Activity className="w-4 h-4"/>}>{ar?'فتح التسجيل':'Open registration'}</Button>}</div></div>{publishSuccess&&<div role="status" className="mt-5 rounded-xl bg-[#E7EEE9] text-[#214C40] p-3 text-xs font-bold">{ar?'تم فتح التسجيل لهذه المسابقة بنجاح.':'Registration is now open for this competition.'}</div>}{publishIssues.length>0&&<div role="status" className="mt-5 rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs font-bold"><div>{ar?'قبل فتح التسجيل أكمل التالي:':'Complete these before opening registration:'}</div><ul className="mt-2 list-disc list-inside space-y-1">{publishIssues.map(x=><li key={x}>{x}</li>)}</ul></div>}</section>
  <section className="grid grid-cols-3 gap-3"><MetricCard icon={UsersRound} value={participants.length} label={ar?'مشارك':'Participants'}/><MetricCard icon={Clock3} value={participants.filter(p=>p.status==='in_queue').length} label={ar?'في الانتظار':'Waiting'}/><MetricCard icon={Gavel} value={committees.filter(c=>c.status!=='offline').length} label={ar?'لجان نشطة':'Active panels'}/></section>
  <section className="grid xl:grid-cols-[1.35fr_.65fr] gap-4 [&>*]:min-w-0">
   <div className="mizan-surface p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><div className="mizan-kicker">{ar?'مسار المسابقة':'LIVE FLOW'}</div><h2 className="font-extrabold mt-1">{ar?'من التسجيل إلى الشهادة':'Registration to certificate'}</h2></div><Badge variant={readiness.length?'amber':'emerald'}>{readiness.length?`${readiness.length} ${ar?'ملاحظات':'items'}`:(ar?'جاهز':'Ready')}</Badge></div><div className="flex items-start gap-2 overflow-x-auto mt-5 pb-1">{getCompetitionPolicy(store.competition).workflow.filter(w=>w.enabled).map((w,i,all)=><React.Fragment key={w.id}><div className="shrink-0 w-14 text-center"><div title={workflowLabel(w.id,ar)} className={`mx-auto w-9 h-9 rounded-xl grid place-items-center text-xs font-black ${w.automated?'bg-[#E7EEE9] text-[#214C40]':'bg-[#F2EADC] text-[#7d5e34]'}`}>{i+1}</div><div className="mt-1.5 text-[9px] sm:text-[10px] font-bold text-[#59615c] leading-4 whitespace-nowrap">{workflowLabel(w.id,ar)}</div></div>{i<all.length-1&&<div className="shrink-0 w-4 h-px bg-[#d9d7d0] mt-[18px]"/>}</React.Fragment>)}</div><div className="mt-4 text-xs text-[#626864]">{ar?'الأخضر مؤتمت · الذهبي قرار بشري':'Green automated · gold human decision'}</div>{getCompetitionPolicy(store.competition).results.requireDualApprovalToSeal&&sealApprovals.length>0&&<div className="text-[11px] text-[#7d5e34] mt-3">{ar?`اعتمادات الختم الحالية: ${new Set(sealApprovals.map(a=>a.actorId)).size}/2`:`Seal approvals: ${new Set(sealApprovals.map(a=>a.actorId)).size}/2`}</div>}</div>
   <div className="mizan-surface p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="mizan-kicker">{ar?'يحتاج انتباهك':'NEEDS ATTENTION'}</div><h2 className="font-extrabold mt-1">{attention.length}</h2></div><CircleAlert className={`w-5 h-5 ${attention.length?'text-[#89673a]':'text-[#2F6555]'}`}/></div><div className="mt-4">{attention.length?attention.slice(0,5).map(x=><div key={x.id} className="py-2.5 border-b border-[#ebe9e3] last:border-0 text-xs font-semibold text-[#454c48]">{x.title}</div>):<div className="py-6 text-center"><BadgeCheck className="w-6 h-6 text-[#2F6555] mx-auto"/><div className="text-xs font-bold mt-2">{ar?'لا شيء يحتاج تدخلك':'Nothing needs intervention'}</div></div>}</div></div>
  </section>
 </div>;
};

const CompetitionDNA=({store,ar,policy,section,setSection,patchPolicy}:{store:Store;ar:boolean;policy:CompetitionPolicy;section:PolicySection;setSection:(s:PolicySection)=>void;patchPolicy:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const {competition}=store; const sections:[PolicySection,React.ComponentType<{className?:string}>,string][]=[['identity',Fingerprint,ar?'الهوية والفئات':'Identity & categories'],['registration',FileCheck2,ar?'التسجيل والشروط':'Registration'],['workflow',Network,ar?'المسار':'Workflow'],['operations',QrCode,ar?'التشغيل':'Operations'],['questions',Sparkles,ar?'الأسئلة':'Questions'],['judging',Gavel,ar?'التحكيم':'Judging'],['appeals',ListChecks,ar?'الاعتراضات':'Appeals'],['results',LockKeyhole,ar?'النتائج':'Results'],['certificate',Award,ar?'الشهادة':'Certificates'],['privacy',ShieldCheck,ar?'الخصوصية':'Privacy']];
 return <div className="space-y-4">
  <div><div className="mizan-kicker">{ar?'بصمة المسابقة':'MIZAN COMPETITION DNA'}</div><h1 className="text-2xl sm:text-3xl font-black mt-1">{ar?'كل مسابقة لها نظامها':'Every competition is its own system'}</h1><p className="text-sm text-[#626864] mt-2 max-w-2xl">{ar?'لا توجد لائحة عالمية مفروضة. كل شرط وكل زر تحكيم وكل مرحلة تخص هذه المسابقة وحدها.':'No global rules are imposed. Registration, judging actions, workflow and policies belong to this competition only.'}</p></div>
  <div className="grid lg:grid-cols-[220px_minmax(0,1fr)] gap-4 min-w-0">
   <div className="mizan-surface p-2 h-fit"><div className="grid grid-cols-2 lg:grid-cols-1 gap-1">{sections.map(([id,Icon,label])=><button key={id} onClick={()=>setSection(id)} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl text-xs sm:text-sm font-bold text-start ${section===id?'bg-[#E7EEE9] text-[#214C40]':'text-[#626a65] hover:bg-[#f2f0ea]'}`}><Icon className="w-4 h-4 shrink-0"/><span className="truncate">{label}</span></button>)}</div></div>
   <div className="mizan-surface p-5 sm:p-7 min-h-[520px] min-w-0 max-w-full overflow-x-hidden">
    {section==='identity'&&<IdentitySection store={store} ar={ar}/>} 
    {section==='registration'&&<RegistrationSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='workflow'&&<WorkflowSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='operations'&&<OperationsPolicySection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='questions'&&<QuestionsSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='judging'&&<JudgingSection store={store} ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='appeals'&&<AppealsSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='results'&&<ResultPolicySection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='certificate'&&<CertificateSection store={store} ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='privacy'&&<PrivacySection ar={ar} policy={policy} patch={patchPolicy}/>} 
   </div>
  </div>
 </div>;
};

const quarterLabel=(units:number,ar:boolean)=>{const n=Math.max(1,Math.round(units));const whole=Math.floor(n/4),rem=n%4;const frac=['','¼','½','¾'][rem];if(!whole)return frac;return ar?`${whole}${frac?` و${frac}`:''} ${whole===1?'وجه':'أوجه'}`:`${whole}${frac?` ${frac}`:''} page${whole===1?'':'s'}`};
const legacyQuarterUnits=(cat:Category)=>cat.pageQuarterUnits||({quarter:1,third:1,half:2,full:4} as Record<string,number>)[cat.pagePortion||'']||1;
const PassageLengthControl=({ar,mode,value,onMode,onValue}:{ar:boolean;mode:'ayat'|'page_quarters';value:number;onMode:(v:'ayat'|'page_quarters')=>void;onValue:(v:number)=>void})=><Control label={ar?'طول مقطع السؤال':'Question passage length'}><div className="rounded-xl border border-[#dcdad2] bg-white p-2"><div className="grid grid-cols-2 gap-1"><button type="button" onClick={()=>onMode('ayat')} className={`min-h-10 rounded-lg text-xs font-black ${mode==='ayat'?'bg-[#214C40] text-white':'bg-[#f3f1eb] text-[#626a65]'}`}>{ar?'بالآيات':'By ayat'}</button><button type="button" onClick={()=>onMode('page_quarters')} className={`min-h-10 rounded-lg text-xs font-black ${mode==='page_quarters'?'bg-[#214C40] text-white':'bg-[#f3f1eb] text-[#626a65]'}`}>{ar?'بالأوجه':'By pages'}</button></div><div className="mt-2 flex items-center justify-between gap-3"><button type="button" aria-label={ar?'إنقاص':'Decrease'} onClick={()=>onValue(Math.max(1,value-1))} className="w-11 h-11 rounded-xl border border-[#dcdad2] text-xl font-black">−</button><div className="min-w-0 flex-1 text-center"><div className="text-lg font-black tabular-nums">{mode==='ayat'?value:quarterLabel(value,ar)}</div><div className="text-[10px] text-[#656b66]">{mode==='ayat'?(ar?'آية لكل سؤال':'ayat per question'):(ar?'الزيادة كل مرة: ربع وجه':'increments by quarter page')}</div></div><button type="button" aria-label={ar?'زيادة':'Increase'} onClick={()=>onValue(value+1)} className="w-11 h-11 rounded-xl border border-[#dcdad2] text-xl font-black">+</button></div></div></Control>;

const IdentitySection=({store,ar}:{store:Store;ar:boolean})=>{
 const c=store.competition;
 const [selected,setSelected]=useState(c.categories[0]?.id||'');
 const cat=c.categories.find(x=>x.id===selected);
 const [adding,setAdding]=useState(false);
 const emptyDraft=()=>({nameArabic:'',name:'',riwaya:'',memorizationScope:'',juzCount:'',passageMode:'ayat' as 'ayat'|'page_quarters',passageValue:1,minAge:'',maxAge:'',genderConstraint:'all' as 'all'|'male'|'female'});
 const [draft,setDraft]=useState(emptyDraft());
 useEffect(()=>{if(!selected&&c.categories[0])setSelected(c.categories[0].id);if(selected&&!c.categories.some(x=>x.id===selected))setSelected(c.categories[0]?.id||'')},[c.categories,selected]);
 const patch=(p:Partial<Competition>)=>store.updateCompetitionDetails(p);
 const patchCat=(p:Partial<Category>)=>cat&&store.updateCategory(cat.id,p);
 const saveCategory=()=>{if(!draft.nameArabic.trim()&&!draft.name.trim())return;const passage=draft.passageMode==='ayat'?{passageMode:'ayat' as const,ayatPerQuestion:Math.max(1,draft.passageValue),pageQuarterUnits:undefined,pagePortion:undefined}:{passageMode:'page_quarters' as const,pageQuarterUnits:Math.max(1,draft.passageValue),ayatPerQuestion:undefined,pagePortion:undefined};const x=store.addCategory({nameArabic:draft.nameArabic.trim()||draft.name.trim(),name:draft.name.trim()||draft.nameArabic.trim(),riwaya:draft.riwaya.trim(),memorizationScope:draft.memorizationScope.trim(),juzCount:Number(draft.juzCount)||0,targetDurationMinutes:c.ruleSet.questionDurationMinutes||8,minAge:Number(draft.minAge)>0?Number(draft.minAge):undefined,maxAge:Number(draft.maxAge)>0?Number(draft.maxAge):undefined,genderConstraint:draft.genderConstraint,...passage});setSelected(x.id);setDraft(emptyDraft());setAdding(false)};
 const [logoBusy,setLogoBusy]=useState(false); const visibleLogo=c.logoUrl&&!c.logoUrl.startsWith('data:')?c.logoUrl:undefined;
 const uploadLogo=async(file?:File)=>{if(!file||logoBusy)return;setLogoBusy(true);try{const url=await uploadCompetitionLogo(c.organizationId,c.id,file);patch({logoUrl:url})}catch(err){const code=err instanceof Error?err.message:'';window.alert(code==='LOGO_TOO_LARGE'?(ar?'حجم الشعار يجب ألا يتجاوز 2MB.':'Logo must be 2MB or smaller.'):(ar?'اختر PNG أو JPG/JPEG أو WebP أو SVG صالحًا.':'Choose a valid PNG, JPG/JPEG, WebP or SVG.'))}finally{setLogoBusy(false)}};
 const removeLogo=async()=>{if(logoBusy)return;setLogoBusy(true);try{if(isManagedBrandLogoUrl(c.logoUrl))await deleteCompetitionLogo(c.organizationId,c.id);patch({logoUrl:undefined})}catch{window.alert(ar?'تعذر حذف ملف الشعار من التخزين.':'Could not remove the stored logo.')}finally{setLogoBusy(false)}};
 const catMode: 'ayat'|'page_quarters'=cat?.passageMode||(cat?.pageQuarterUnits||cat?.pagePortion?'page_quarters':'ayat');
 const catPassageValue=cat?(catMode==='ayat'?Math.max(1,cat.ayatPerQuestion||1):legacyQuarterUnits(cat)):1;
 return <div className="space-y-6"><SectionTitle title={ar?'هوية المسابقة':'Competition identity'} subtitle={ar?'بيانات المسابقة في الأعلى، والفئات تُضاف وتحفظ بشكل مستقل في الأسفل.':'Competition details are above; categories are added and saved independently below.'}/>
  <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 [&>*]:min-w-0"><TextControl label={ar?'الاسم بالعربية':'Arabic name'} value={c.nameArabic} onChange={v=>patch({nameArabic:v})}/><TextControl label={ar?'الاسم بالإنجليزية':'English name'} value={c.name} onChange={v=>patch({name:v})}/><TextControl label={ar?'المنطقة الزمنية':'Timezone'} value={c.timezone} onChange={v=>patch({timezone:v})}/><TextControl label={ar?'المكان':'Venue'} value={c.venueName} onChange={v=>patch({venueName:v})}/><TextControl type="date" label={ar?'بداية المسابقة':'Start date'} value={c.startDate} onChange={v=>patch({startDate:v})}/><TextControl type="date" label={ar?'نهاية المسابقة':'End date'} value={c.endDate} onChange={v=>patch({endDate:v})}/><Control label={ar?'الأتمتة':'Automation'}><TinySelect value={c.automationLevel} onChange={v=>patch({automationLevel:v as any})}><option value="assisted">{automationLevelLabel('assisted',ar)}</option><option value="automated">{automationLevelLabel('automated',ar)}</option><option value="autopilot">{automationLevelLabel('autopilot',ar)}</option></TinySelect></Control><TextControl label={ar?'اسم العلامة لهذه المسابقة (يظهر بدل «ميزان»)':'Wordmark for this competition (replaces “MIZAN”)'} value={ar?(c.displayNameArabic||''):(c.displayName||'')} onChange={v=>patch(ar?{displayNameArabic:v||undefined}:{displayName:v||undefined})}/><Control label={ar?'شعار هذه المسابقة':'Competition logo'}><div className="rounded-xl border border-[#dcdad2] bg-white p-3"><div className="flex flex-col sm:flex-row sm:items-center gap-3">{visibleLogo?<img src={visibleLogo} alt={ar?'شعار المسابقة':'Competition logo'} className="w-16 h-16 rounded-xl object-contain border bg-white"/>:<div className="w-16 h-16 rounded-xl border border-dashed grid place-items-center text-[10px] text-[#777]">{ar?'لا شعار':'No logo'}</div>}<label aria-disabled={logoBusy} className={`min-h-11 px-4 rounded-xl bg-[#214C40] text-white text-xs font-black inline-flex items-center justify-center gap-2 cursor-pointer ${logoBusy?'opacity-60 pointer-events-none':''}`}><FileUp className="w-4 h-4"/>{logoBusy?(ar?'جارٍ الحفظ…':'Saving…'):(visibleLogo?(ar?'استبدال الشعار':'Replace logo'):(ar?'رفع الشعار':'Upload logo'))}<input type="file" accept=".png,.jpg,.jpeg,.webp,.svg,image/png,image/jpeg,image/webp,image/svg+xml" className="sr-only" onChange={e=>{void uploadLogo(e.target.files?.[0]);e.currentTarget.value=''}}/></label>{c.logoUrl&&<button type="button" disabled={logoBusy} onClick={()=>void removeLogo()} className="min-h-11 px-4 rounded-xl border text-xs font-black disabled:opacity-50">{ar?'حذف':'Remove'}</button>}</div><p className="mt-2 text-[10px] text-[#656b66]">{ar?'PNG أو JPG/JPEG أو WebP أو SVG — بحد أقصى 2MB. يُحفظ الملف في التخزين الفعلي ولا يُخزن داخل بيانات المسابقة.':'PNG, JPG/JPEG, WebP or SVG — max 2MB. The file is stored in object storage, never inside competition state.'}</p></div></Control></div>
  <div className="border-t border-[#e5e3dc] pt-5"><div className="flex items-center justify-between gap-3"><div><div className="text-sm font-black">{ar?'الفئات':'Categories'}</div><p className="text-[10px] text-[#656b66] mt-1">{ar?'لا توجد فئة افتراضية. أضف الفئة التي تريدها ثم احفظها.':'There is no default category. Add the category you need, then save it.'}</p></div><button type="button" onClick={()=>setAdding(true)} className="min-h-11 px-3 rounded-xl inline-flex items-center gap-1 text-xs font-black text-[#214C40] border border-[#cddbd3] bg-white"><Plus className="w-4 h-4"/>{ar?'فئة':'Category'}</button></div>{!c.categories.length&&!adding&&<div className="mt-4 rounded-xl bg-[#f7f5ef] p-5 text-center text-xs text-[#656b66]">{ar?'لا توجد فئات بعد. اضغط «+ فئة» لإضافة الأولى.':'No categories yet. Press “+ Category” to add the first one.'}</div>}{c.categories.length>0&&<div className="flex gap-2 overflow-x-auto mt-3">{c.categories.map(x=><button key={x.id} onClick={()=>{setSelected(x.id);setAdding(false)}} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold border ${selected===x.id&&!adding?'bg-[#E7EEE9] text-[#214C40] border-[#b7ccc2]':'border-[#deddd6] bg-white text-[#626a65]'}`}>{ar?x.nameArabic:x.name}</button>)}</div>}</div>
  {adding&&<div className="rounded-2xl border border-[#cddbd3] bg-[#F7FAF8] p-4 sm:p-5 space-y-4"><div className="text-sm font-black">{ar?'إضافة فئة جديدة':'Add new category'}</div><div className="grid grid-cols-1 xl:grid-cols-2 gap-3 [&>*]:min-w-0"><TextControl label={ar?'اسم الفئة عربي':'Arabic category'} value={draft.nameArabic} onChange={v=>setDraft(d=>({...d,nameArabic:v}))}/><TextControl label={ar?'اسم الفئة إنجليزي':'English category'} value={draft.name} onChange={v=>setDraft(d=>({...d,name:v}))}/><TextControl label={ar?'الرواية / القراءة':'Riwaya / Qira’a'} value={draft.riwaya} onChange={v=>setDraft(d=>({...d,riwaya:v}))}/><TextControl label={ar?'نطاق الحفظ':'Scope'} value={draft.memorizationScope} onChange={v=>setDraft(d=>({...d,memorizationScope:v}))}/><DraftNumber label={ar?'الأجزاء':'Juz'} value={draft.juzCount} onChange={v=>setDraft(d=>({...d,juzCount:v}))}/><PassageLengthControl ar={ar} mode={draft.passageMode} value={draft.passageValue} onMode={v=>setDraft(d=>({...d,passageMode:v,passageValue:1}))} onValue={v=>setDraft(d=>({...d,passageValue:v}))}/><DraftNumber label={ar?'العمر الأدنى':'Minimum age'} value={draft.minAge} onChange={v=>setDraft(d=>({...d,minAge:v}))}/><DraftNumber label={ar?'العمر الأعلى':'Maximum age'} value={draft.maxAge} onChange={v=>setDraft(d=>({...d,maxAge:v}))}/><Control label={ar?'الجنس حسب الشروط':'Gender constraint'}><TinySelect value={draft.genderConstraint} onChange={v=>setDraft(d=>({...d,genderConstraint:v as any}))}><option value="all">{ar?'الكل':'All'}</option><option value="male">{ar?'رجال':'Male'}</option><option value="female">{ar?'نساء':'Female'}</option></TinySelect></Control></div><div className="rounded-xl bg-[#f0eee8] px-3 py-2 text-[10px] text-[#656b66]">{ar?'عدد الأسئلة والزمن التشغيلي يُداران داخليًا من سياسة المسابقة ولا يثقلان نموذج الفئة.':'Question count and operational timing are managed internally by competition policy, not by this category form.'}</div><div className="flex justify-end gap-2"><Button size="sm" variant="ghost" onClick={()=>{setDraft(emptyDraft());setAdding(false)}}>{ar?'إلغاء':'Cancel'}</Button><Button size="sm" disabled={!draft.nameArabic.trim()&&!draft.name.trim()} onClick={saveCategory}>{ar?'حفظ الفئة':'Save category'}</Button></div></div>}
  {!adding&&cat&&<div className="rounded-2xl bg-[#f4f2ec] p-4 sm:p-5 space-y-4"><div className="grid grid-cols-1 xl:grid-cols-2 gap-3 [&>*]:min-w-0"><TextControl label={ar?'اسم الفئة عربي':'Arabic category'} value={cat.nameArabic} onChange={v=>patchCat({nameArabic:v})}/><TextControl label={ar?'اسم الفئة إنجليزي':'English category'} value={cat.name} onChange={v=>patchCat({name:v})}/><TextControl label={ar?'الرواية / القراءة':'Riwaya / Qira’a'} value={cat.riwaya} onChange={v=>patchCat({riwaya:v})}/><TextControl label={ar?'نطاق الحفظ':'Scope'} value={cat.memorizationScope} onChange={v=>patchCat({memorizationScope:v})}/><NumberControl label={ar?'الأجزاء':'Juz'} value={cat.juzCount} onChange={v=>patchCat({juzCount:v})}/><PassageLengthControl ar={ar} mode={catMode} value={catPassageValue} onMode={v=>patchCat(v==='ayat'?{passageMode:'ayat',ayatPerQuestion:1,pageQuarterUnits:undefined,pagePortion:undefined}:{passageMode:'page_quarters',pageQuarterUnits:1,ayatPerQuestion:undefined,pagePortion:undefined})} onValue={v=>patchCat(catMode==='ayat'?{passageMode:'ayat',ayatPerQuestion:v,pageQuarterUnits:undefined,pagePortion:undefined}:{passageMode:'page_quarters',pageQuarterUnits:v,ayatPerQuestion:undefined,pagePortion:undefined})}/><NumberControl label={ar?'العمر الأدنى':'Minimum age'} value={cat.minAge||0} onChange={v=>patchCat({minAge:v||undefined})}/><NumberControl label={ar?'العمر الأعلى':'Maximum age'} value={cat.maxAge||0} onChange={v=>patchCat({maxAge:v||undefined})}/><Control label={ar?'الجنس حسب الشروط':'Gender constraint'}><TinySelect value={cat.genderConstraint||'all'} onChange={v=>patchCat({genderConstraint:v as any})}><option value="all">{ar?'الكل':'All'}</option><option value="male">{ar?'رجال':'Male'}</option><option value="female">{ar?'نساء':'Female'}</option></TinySelect></Control><Control label={ar?'لائحة التحكيم':'Rule set'}><TinySelect value={cat.ruleSetId||c.ruleSet.id} onChange={v=>patchCat({ruleSetId:v})}>{(c.ruleSets||[c.ruleSet]).map(r=><option key={r.id} value={r.id}>{r.name} · {r.version}</option>)}</TinySelect></Control></div><div className="flex justify-end"><Button size="sm" variant="ghost" disabled={store.participants.some(p=>p.categoryId===cat.id)} onClick={()=>{if(store.removeCategory(cat.id))setSelected(c.categories.find(x=>x.id!==cat.id)?.id||'')}} icon={<Trash2 className="w-4 h-4"/>}>{ar?'حذف الفئة':'Remove category'}</Button></div></div>}
  <ShareRegistration c={c} ar={ar}/>
 </div>;
};
const DraftNumber=({label,value,onChange}:{label:string;value:string;onChange:(v:string)=>void})=><Control label={label}><input type="number" min="0" value={value} onChange={e=>onChange(e.target.value.replace(/[^0-9.]/g,''))} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold" dir="ltr"/></Control>;

const RegistrationSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'التسجيل والشروط':'Registration & rules'} subtitle={ar?'المتسابق يرى فقط الحقول والشروط التي تحتاجها هذه المسابقة.':'Participants see only the fields and rules used by this competition.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.registration.autoApproveEligible} onChange={v=>patch(p=>{p.registration.autoApproveEligible=v})} label={ar?'اعتماد تلقائي إذا استوفى الشروط':'Auto-approve when rules are met'}/><Toggle value={policy.registration.requireGuardianForMinors} onChange={v=>patch(p=>{p.registration.requireGuardianForMinors=v})} label={ar?'ولي أمر للقاصر':'Guardian for minors'}/></div><div><div className="text-xs font-black text-[#606662] mb-2">{ar?'حقول التسجيل':'Registration fields'}</div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{policy.registration.fields.map((f,i)=><RegistrationFieldRow key={f.id} f={f} ar={ar} onVisible={v=>patch(p=>{p.registration.fields[i].visible=v})} onRequired={v=>patch(p=>{p.registration.fields[i].required=v})}/>)}</div></div><div className="rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs">{ar?'شروط الفئة مثل العمر والجنس والنطاق تُطبّق فوق هذه الحقول، وأي حالة غير محسومة تذهب للمراجعة البشرية.':'Category rules such as age, gender and scope apply on top of these fields; unresolved cases go to human review.'}</div></div>;

const WorkflowSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'المسار والأتمتة':'Workflow & automation'} subtitle={ar?'كل مرحلة يمكن تشغيلها أو أتمتتها أو اشتراط اعتماد بشري.':'Each stage can be enabled, automated, or approval-gated.'}/><div className="divide-y divide-[#e6e4dd]">{policy.workflow.map((w,i)=><div key={w.id} className="py-3 grid grid-cols-[36px_1fr_auto] items-center gap-3"><span className="w-8 h-8 rounded-xl bg-[#f0eee8] grid place-items-center text-xs font-black">{i+1}</span><div><div className="text-sm font-bold">{workflowLabel(w.id,ar)}</div><div className="text-[11px] text-[#666b67]">{!w.enabled?(ar?'متوقف':'Disabled'):w.automated?(ar?'آلي':'Automated'):(ar?'بشري':'Human')}</div></div><div className="flex gap-1"><Chip active={w.enabled} onClick={()=>patch(p=>{p.workflow[i].enabled=!p.workflow[i].enabled})}>{w.enabled?(ar?'مفعّل':'On'):(ar?'متوقف':'Off')}</Chip>{w.enabled&&<Chip active={w.automated} amber={!w.automated} onClick={()=>patch(p=>{p.workflow[i].automated=!p.workflow[i].automated})}>{w.automated?(ar?'آلي':'Auto'):(ar?'بشري':'Human')}</Chip>}{w.enabled&&<Chip active={w.requiresApproval} amber onClick={()=>patch(p=>{p.workflow[i].requiresApproval=!p.workflow[i].requiresApproval})}>{ar?'اعتماد':'Approval'}</Chip>}</div></div>)}</div></div>;

/* مشاركة رابط تسجيل هذه المسابقة: رابط مباشر (#register?comp=..) + رمز QR للطباعة/النشر. */
const ShareRegistration:React.FC<{c:Competition;ar:boolean}>=({c,ar})=>{
 const [copied,setCopied]=useState(false);
 const origin=typeof window!=='undefined'?window.location.origin:'';
 const link=`${origin}/#register?comp=${c.id}`;
 const copy=async()=>{try{await navigator.clipboard.writeText(link);setCopied(true);window.setTimeout(()=>setCopied(false),1800)}catch{/* المتصفح منع النسخ */}};
 return <div className="mizan-surface p-5"><div className="mizan-kicker">{ar?'مشاركة التسجيل':'SHARE REGISTRATION'}</div><h2 className="font-extrabold mt-1">{ar?'رابط تسجيل هذه المسابقة':'This competition’s registration link'}</h2>
  <div className="mt-4 grid sm:grid-cols-[1fr_auto] gap-4 items-center"><div className="min-w-0"><div dir="ltr" className="rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-xs font-mono truncate">{link}</div><div className="flex gap-2 mt-3"><Button size="sm" onClick={()=>void copy()}>{copied?(ar?'تم النسخ':'Copied'):(ar?'انسخ الرابط':'Copy link')}</Button><a href={link} className="inline-flex items-center rounded-xl border border-[#dcdad2] px-3 py-2 text-xs font-bold text-[#214C40]">{ar?'فتح':'Open'}</a></div><p className="text-[10px] text-[#696f6b] mt-3">{ar?'أرسل هذا الرابط للمتسابقين؛ يفتح نموذج تسجيل هذه المسابقة مباشرة.':'Send this link to participants; it opens this competition’s registration form directly.'}</p></div><div className="bg-white p-2 rounded-2xl border border-[#deddd6] justify-self-center"><RealQRCode value={link} size={120}/></div></div></div>;
};

const OperationsPolicySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'سياسة التشغيل':'Operations policy'} subtitle={ar?'حدد إلى أي مدى تعمل المسابقة بلا موظفي استقبال أو توزيع يدوي.':'Choose how far the competition can run without reception or manual routing.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.operations.selfCheckIn} onChange={v=>patch(p=>{p.operations.selfCheckIn=v})} label={ar?'حضور ذاتي من الهاتف':'Mobile self check-in'}/><Toggle value={policy.operations.kioskCheckIn} onChange={v=>patch(p=>{p.operations.kioskCheckIn=v})} label={ar?'تسجيل ذاتي':'Self-service kiosk'}/><Toggle value={policy.operations.exceptionDesk} onChange={v=>patch(p=>{p.operations.exceptionDesk=v})} label={ar?'مكتب استثناء للحالات النادرة':'Exception desk'}/><Toggle value={policy.operations.smartArrivalSlots} onChange={v=>patch(p=>{p.operations.smartArrivalSlots=v})} label={ar?'مواعيد حضور ذكية':'Smart arrival slots'}/><Toggle value={policy.operations.autoRouting} onChange={v=>patch(p=>{p.operations.autoRouting=v})} label={ar?'توزيع تلقائي على اللجان':'Automatic committee routing'}/><Toggle value={policy.operations.publicQueueUsesCodesOnly} onChange={v=>patch(p=>{p.operations.publicQueueUsesCodesOnly=v})} label={ar?'الشاشات العامة تستخدم الأكواد':'Public queue uses codes only'}/><Toggle value={policy.operations.offlineContinuity} onChange={v=>patch(p=>{p.operations.offlineContinuity=v})} label={ar?'استمرارية دون إنترنت':'Offline continuity'}/></div><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'مهلة التأخر بالدقائق':'Late grace minutes'} value={policy.operations.lateArrivalGraceMinutes} onChange={v=>patch(p=>{p.operations.lateArrivalGraceMinutes=v})}/><Control label={ar?'البطاقة':'Badge'}><TinySelect value={policy.operations.badgeMode} onChange={v=>patch(p=>{p.operations.badgeMode=v as any})}><option value="digital">{ar?'رقمية':'Digital'}</option><option value="print">{ar?'مطبوعة':'Print'}</option><option value="both">{ar?'الاثنان':'Both'}</option><option value="none">{ar?'بدون':'None'}</option></TinySelect></Control></div></div>;

const QuestionsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const reveal=policy.questions.secureReveal||{requireParticipantPresence:true,judgeApprovalMode:'all_assigned' as const};
 const opening=policy.questions.openingPrompt||{mode:'approved_reference_audio' as const,autoplay:true,usageScope:'opening_prompt',preferredReciter:''};
 const cue=policy.questions.transitionCue||{enabled:true,phraseArabic:'',phraseEnglish:'',selectedPhraseIndexes:[0],autoAdvanceDelayMs:900};
 const phrases=ar?TRANSITION_PHRASES_AR:TRANSITION_PHRASES_EN;
 const legacyPhrase=ar?cue.phraseArabic:cue.phraseEnglish;
 const legacyIndex=legacyPhrase?phrases.indexOf(legacyPhrase):-1;
 const validSelected=(cue.selectedPhraseIndexes||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<phrases.length);
 const selected=[...new Set(validSelected.length?validSelected:[legacyIndex>=0?legacyIndex:0])];
 const setSelected=(next:number[])=>patch(p=>{const current=p.questions.transitionCue||{enabled:true,phraseArabic:'',phraseEnglish:'',autoAdvanceDelayMs:900};p.questions.transitionCue={...current,phraseArabic:'',phraseEnglish:'',audioUrl:undefined,selectedPhraseIndexes:[...new Set(next)].sort((a,b)=>a-b)}});
 const togglePhrase=(idx:number)=>{const next=selected.includes(idx)?selected.filter(x=>x!==idx):[...selected,idx];if(next.length)setSelected(next)};
 return <div className="space-y-5"><SectionTitle title={ar?'السحب العادل والأسئلة':'FairDraw & questions'} subtitle={ar?'حدد كيف يُختار السؤال، ومتى يُكشف، وكيف تبدأ التلاوة وتنتهي دون أن يرى المحكم السؤال مبكرًا.':'Define how a question is selected, revealed, opened and ended without early exposure.'}/>
  <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"><Control label={ar?'طريقة السحب':'Draw mode'}><TinySelect value={policy.questions.drawMode} onChange={v=>patch(p=>{p.questions.drawMode=v as any})}><option value="fairdraw">{ar?'السحب العادل القابل للتحقق':'FairDraw'}</option><option value="pure_random">{ar?'عشوائي':'Pure random'}</option><option value="manual_approved">{ar?'معتمد يدوي':'Approved manual'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد الأسئلة':'Questions'} value={policy.questions.questionsPerParticipant} onChange={v=>patch(p=>{p.questions.questionsPerParticipant=Math.max(1,v)})}/><NumberControl label={ar?'الصعوبة المستهدفة':'Target difficulty'} step={0.1} value={policy.questions.targetDifficulty} onChange={v=>patch(p=>{p.questions.targetDifficulty=v})}/><NumberControl label={ar?'هامش الصعوبة':'Difficulty tolerance'} step={0.05} value={policy.questions.difficultyTolerance} onChange={v=>patch(p=>{p.questions.difficultyTolerance=Math.max(0,v)})}/><Control label={ar?'طريقة البداية':'Prompt mode'}><TinySelect value={policy.questions.promptMode} onChange={v=>patch(p=>{p.questions.promptMode=v as any})}><option value="configurable">{ar?'حسب الإعداد':'Configurable'}</option><option value="judge">{ar?'المحكم':'Judge'}</option><option value="certified_audio">{ar?'صوت بشري معتمد':'Certified human audio'}</option><option value="visual">{ar?'مرئي':'Visual'}</option></TinySelect></Control></div>
  <details className="mizan-surface-soft px-4 py-1"><summary className="cursor-pointer select-none list-none py-3 flex items-center justify-between gap-2 text-xs font-black text-[#59615c]"><span>{ar?'إعدادات السحب المتقدمة — اختيارية':'Advanced draw settings — optional'}</span><span className="text-[10px] font-bold text-[#656b66]">{ar?'حسب سياسة المسابقة':'competition policy'}</span></summary><div className="pb-1"><div className="mb-3 rounded-xl border border-[#d9e4de] bg-[#F7FAF8] p-3 text-[11px] font-bold leading-5 text-[#214C40]">{ar?'يبدأ ميزان السحب العادل تلقائيًا عند بدء جلسة المتسابق؛ لا يحتاج المتسابق إلى زر سحب ولا يمكن تحويل هذه المسؤولية إليه.':'MIZAN starts FairDraw automatically when the participant session begins; there is no participant draw button and this responsibility cannot be delegated.'}</div><Toggle value={policy.questions.avoidRepeatWithinRound} onChange={v=>patch(p=>{p.questions.avoidRepeatWithinRound=v})} label={ar?'تجنب التكرار داخل الجولة':'Avoid repeats within round'}/><Toggle value={policy.questions.diversity.acrossJuz} onChange={v=>patch(p=>{p.questions.diversity.acrossJuz=v})} label={ar?'تنوع بين الأجزاء':'Across-Juz diversity'}/><Toggle value={policy.questions.diversity.acrossSurah} onChange={v=>patch(p=>{p.questions.diversity.acrossSurah=v})} label={ar?'تنوع بين السور':'Across-Surah diversity'}/><Toggle value={policy.questions.diversity.mutashabihatBalance} onChange={v=>patch(p=>{p.questions.diversity.mutashabihatBalance=v})} label={ar?'موازنة المتشابهات':'Mutashabihat balance'}/></div></details>
  <div className="grid lg:grid-cols-2 gap-3"><div className="mizan-surface p-4"><div className="mizan-kicker">{ar?'منع كشف السؤال مبكرًا':'SECURE REVEAL'}</div><div className="mt-3"><Toggle value={reveal.requireParticipantPresence} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,requireParticipantPresence:v}})} label={ar?'لا كشف قبل وجود المتسابق أمام اللجنة':'Require participant presence'}/></div><Control label={ar?'موافقة المحكمين':'Judge approval'}><TinySelect value={reveal.judgeApprovalMode} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,judgeApprovalMode:v as 'all_assigned'|'minimum'}})}><option value="all_assigned">{ar?'جميع المحكمين المكلّفين':'All assigned judges'}</option><option value="minimum">{ar?'حد أدنى محدد':'Configured minimum'}</option></TinySelect></Control>{reveal.judgeApprovalMode==='minimum'&&<div className="mt-3"><NumberControl label={ar?'الحد الأدنى للموافقات':'Minimum approvals'} value={reveal.minimumApprovals||1} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,minimumApprovals:Math.max(1,v)}})}/></div>}<p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'الوضع الأعلى نزاهة هو موافقة كل المحكمين بعد حضور المتسابق.':'Highest-integrity mode requires every assigned judge after participant presence.'}</p></div><div className="mizan-surface p-4"><div className="mizan-kicker">{ar?'بداية التلاوة':'OPENING AYAH'}</div><div className="mt-3"><Toggle value={opening.autoplay} onChange={v=>patch(p=>{p.questions.openingPrompt={...opening,autoplay:v}})} label={ar?'تشغيل أول آية تلقائيًا بعد كشف السؤال':'Autoplay first ayah after reveal'}/></div><p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'يُشغَّل أول آية للسؤال بصوت القارئ المعتمد المتفق عليه — لا يوجد تحويل آلي للنص القرآني إلى صوت.':'The question’s first ayah plays from the agreed approved reciter — Quran audio is never synthesized.'}</p></div></div>
  <div className="mizan-surface p-4 sm:p-5"><div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3"><div><div className="mizan-kicker">{ar?'إنهاء الموضع':'PASSAGE END'}</div><h3 className="font-black mt-1">{ar?'عبارات إنهاء هادئة ومتنوعة':'Calm, varied stop cues'}</h3><p className="text-[10px] leading-5 text-[#656b66] mt-1 max-w-xl">{ar?'اختر عبارة واحدة أو عدة عبارات أو الكل. عند اختيار أكثر من واحدة يتناوب ميزان بينها تلقائيًا، ولا يوجد رفع تسجيل يدوي أو نص حر.':'Choose one, several, or all. MIZAN rotates selected cues automatically; there is no manual recording upload or free-text cue.'}</p></div><Toggle value={cue.enabled} onChange={v=>patch(p=>{p.questions.transitionCue={...cue,enabled:v}})} label={ar?'التنبيه الصوتي مفعّل':'Audio cue enabled'}/></div><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={()=>setSelected(phrases.map((_,i)=>i))} className={`rounded-xl px-3 py-2 text-xs font-black border ${selected.length===phrases.length?'bg-[#214C40] text-white border-[#214C40]':'bg-white border-[#deddd6] text-[#214C40]'}`}>{ar?'اختيار الكل':'Select all'}</button><button type="button" onClick={()=>setSelected([selected[0]??0])} className="rounded-xl px-3 py-2 text-xs font-black border border-[#deddd6] bg-white text-[#59615c]">{ar?'واحدة فقط':'One only'}</button><span className="self-center text-[10px] text-[#656b66]">{ar?`${selected.length} مختارة`:`${selected.length} selected`}</span></div><div className="mt-3 grid md:grid-cols-2 gap-2">{phrases.map((phrase,idx)=>{const on=selected.includes(idx);return <button type="button" key={phrase} onClick={()=>togglePhrase(idx)} aria-pressed={on} className={`rounded-xl border px-3 py-3 text-start text-xs font-bold leading-5 transition ${on?'border-[#b7ccc2] bg-[#E7EEE9] text-[#214C40]':'border-[#e2e0d9] bg-[#fffefb] text-[#5e6661] hover:bg-[#f7f5ef]'}`}><span className="inline-flex w-5 h-5 me-2 rounded-full border items-center justify-center text-[10px] align-middle">{on?'✓':idx+1}</span>{phrase}</button>})}</div><div className="mt-4 max-w-sm"><NumberControl label={ar?'مهلة الانتقال بالمللي ثانية':'Transition delay (ms)'} value={cue.autoAdvanceDelayMs} onChange={v=>patch(p=>{p.questions.transitionCue={...cue,autoAdvanceDelayMs:Math.max(0,v)}})}/></div><p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'يبدأ ميزان بالمقطع الصوتي المطابق المدمج، ثم يستخدم صوت الخادم لنفس العبارة غير القرآنية، ثم نطق الجهاز كحل أخير. لا يُرسل أي نص قرآني إلى تحويل النص إلى صوت.':'MIZAN first uses the matching built-in recording, then server speech for the same non-Quran cue, then device speech as a final fallback. Quran text is never sent to text-to-speech.'}</p></div>
 </div>;
};

const JudgingSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const r=store.competition.ruleSet;
 const setCriteria=(criteria:typeof r.criteria)=>store.updateRuleSet({criteria});
 const patchCriterion=(i:number,next:Partial<(typeof r.criteria)[number]>)=>{const criteria=[...r.criteria];criteria[i]={...criteria[i],...next};setCriteria(criteria)};
 const addCriterion=()=>setCriteria([...r.criteria,{id:`criterion-${Date.now()}`,name:'New criterion',nameArabic:'معيار جديد',maxScore:10,weight:0,assignedJudgeType:'all'}]);
 const removeCriterion=(id:string)=>{if(r.criteria.length<=1)return;setCriteria(r.criteria.filter(c=>c.id!==id));patch(p=>{p.judging.actions.forEach(a=>{if(a.criterion===id){a.criterion='custom';a.enabled=false}})})};
 return <div className="space-y-5"><SectionTitle title={ar?'سياسة التحكيم':'Judging policy'} subtitle={ar?'ابنِ معايير هذه المسابقة وأزرار محكميها كما تنص لائحتها؛ لا توجد معايير مفروضة من ميزان.':'Build this competition’s criteria and judge actions from its own rulebook; MIZAN imposes no scoring schema.'}/><div className="grid grid-cols-1 xl:grid-cols-2 gap-4 [&>*]:min-w-0"><Control label={ar?'توزيع المهام':'Judge responsibilities'}><TinySelect value={policy.judging.mode} onChange={v=>patch(p=>{p.judging.mode=v as any})}><option value="all_judges_all_criteria">{ar?'الجميع لكل المعايير':'All judges / all criteria'}</option><option value="specialized_judges">{ar?'تخصص':'Specialized'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><Control label={ar?'الهوية التي يراها المحكم':'Identity'}><TinySelect value={policy.judging.identityVisibility} onChange={v=>patch(p=>{p.judging.identityVisibility=v as any})}><option value="code_only">{ar?'الكود فقط':'Code only'}</option><option value="full">{ar?'كاملة':'Full'}</option><option value="custom">{ar?'مخصصة':'Custom'}</option></TinySelect></Control><Control label={ar?'طريقة إدخال الدرجة':'Score input'}><TinySelect value={policy.judging.scoreEntryMode} onChange={v=>patch(p=>{p.judging.scoreEntryMode=v as any})}><option value="event_based">{ar?'بالأحداث':'Event based'}</option><option value="direct_score">{ar?'درجة مباشرة':'Direct score'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد المحكمين':'Judges per panel'} value={r.judgesCountPerPanel} onChange={v=>store.updateRuleSet({judgesCountPerPanel:Math.max(1,v)})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.judging.independentUntilLock} onChange={v=>patch(p=>{p.judging.independentUntilLock=v})} label={ar?'مستقل حتى القفل':'Independent until lock'}/><Toggle value={policy.judging.requireAudioRecording} onChange={v=>patch(p=>{p.judging.requireAudioRecording=v})} label={ar?'تسجيل الصوت مطلوب':'Audio recording required'}/><Toggle value={policy.judging.allowPhysicalJudgePad} onChange={v=>patch(p=>{p.judging.allowPhysicalJudgePad=v})} label={ar?'لوحة المحكم والاختصارات':'Judge Pad / shortcuts'}/><Toggle value={policy.judging.silentAiGuardian} onChange={v=>patch(p=>{p.judging.silentAiGuardian=v})} label={ar?'الذكاء الاصطناعي صامت للمراجعة فقط':'Silent AI review only'}/><Toggle value={policy.judging.calibrationRequired} onChange={v=>patch(p=>{p.judging.calibrationRequired=v})} label={ar?'معايرة المحكمين':'Judge calibration'}/><Toggle value={policy.judging.reserveJudgeAllowed} onChange={v=>patch(p=>{p.judging.reserveJudgeAllowed=v})} label={ar?'محكم احتياط':'Reserve judge'}/><Toggle value={policy.judging.showRunningScoreToJudge!==false} onChange={v=>patch(p=>{p.judging.showRunningScoreToJudge=v})} label={ar?'إظهار مجموع الخصم للمحكم أثناء التلاوة':'Show running deduction total to judge'}/><Toggle value={policy.judging.allowJudgeUndo!==false} onChange={v=>patch(p=>{p.judging.allowJudgeUndo=v})} label={ar?'السماح للمحكم بالتراجع عن آخر ملاحظة':'Allow judge to undo last mark'}/><Toggle value={r.dropExtremes} onChange={v=>store.updateRuleSet({dropExtremes:v})} label={ar?'إسقاط أعلى وأدنى درجة':'Drop highest and lowest'}/></div><div className="rounded-2xl border border-[#dfddd6] overflow-hidden"><div className="px-4 py-3 bg-[#f7f5ef] flex items-center justify-between gap-3"><div><div className="text-xs font-black text-[#303733]">{ar?'معايير الدرجة':'Score criteria'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'الاسم والدرجة والوزن واختصاص المحكم كلها قابلة للبناء لهذه المسابقة.':'Names, maximums, weights and judge ownership are competition-defined.'}</div></div><button type="button" onClick={addCriterion} className="flex items-center gap-1 text-xs font-black text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'معيار':'Criterion'}</button></div><div className="divide-y divide-[#e5e3dc]">{r.criteria.map((c,i)=><div key={c.id} className="p-3 grid grid-cols-1 2xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)_90px_80px_150px_auto] gap-2 items-center [&>*]:min-w-0"><input aria-label={ar?'اسم المعيار بالعربية':'Arabic criterion name'} value={c.nameArabic} onChange={e=>patchCriterion(i,{nameArabic:e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs font-bold"/><input aria-label={ar?'اسم المعيار بالإنجليزية':'English criterion name'} value={c.name} onChange={e=>patchCriterion(i,{name:e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><input aria-label={ar?'الدرجة القصوى':'Maximum score'} type="number" min="0" step=".25" value={c.maxScore} onChange={e=>patchCriterion(i,{maxScore:Math.max(0,Number(e.target.value))})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><input aria-label={ar?'الوزن':'Weight'} type="number" min="0" max="1" step=".05" value={c.weight} onChange={e=>patchCriterion(i,{weight:Math.max(0,Math.min(1,Number(e.target.value)))})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><select aria-label={ar?'اختصاص المحكم':'Judge specialty'} value={c.assignedJudgeType||'all'} onChange={e=>patchCriterion(i,{assignedJudgeType:e.target.value as any})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"><option value="all">{ar?'كل المحكمين':'All judges'}</option><option value="memorization">{ar?'محكم الحفظ':'Memorization judge'}</option><option value="tajweed">{ar?'محكم التجويد':'Tajweed judge'}</option><option value="performance">{ar?'محكم الأداء':'Performance judge'}</option></select><button type="button" disabled={r.criteria.length<=1} onClick={()=>removeCriterion(c.id)} aria-label={ar?'حذف المعيار':'Remove criterion'} className="w-11 h-11 rounded-lg hover:bg-[#f2e8e5] disabled:opacity-25 text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div><div><div className="flex items-center justify-between mb-2"><div><div className="text-xs font-black text-[#606662]">{ar?'أزرار المحكم':'Judge actions'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'اربط كل زر بمعيار من معاييرك، أو اجعله مخصصًا بلا خصم على معيار.':'Bind each action to one of your criteria, or keep it custom.'}</div></div><button type="button" onClick={()=>patch(p=>p.judging.actions.push({id:`custom-${Date.now()}`,eventType:`custom_${Date.now()}`,labelArabic:'إجراء',labelEnglish:'Action',shortArabic:'إجراء',shortEnglish:'Action',criterion:r.criteria[0]?.id||'custom',penalty:0,enabled:true,icon:'custom'}))} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'إجراء':'Action'}</button></div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{policy.judging.actions.map((a,i)=><div key={a.id} className="py-3 grid grid-cols-1 xl:grid-cols-[minmax(0,1fr)_160px_85px_auto_auto] gap-2 items-center [&>*]:min-w-0"><input value={ar?a.labelArabic:a.labelEnglish} onChange={e=>patch(p=>{if(ar)p.judging.actions[i].labelArabic=e.target.value;else p.judging.actions[i].labelEnglish=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm font-bold"/><select value={a.criterion} onChange={e=>patch(p=>{p.judging.actions[i].criterion=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs">{r.criteria.map(c=><option key={c.id} value={c.id}>{ar?c.nameArabic:c.name}</option>)}<option value="custom">{ar?'مخصص بلا معيار':'Custom / no criterion'}</option></select><input aria-label={ar?'قيمة الخصم':'Penalty'} type="number" step=".25" min="0" value={a.penalty} onChange={e=>patch(p=>{p.judging.actions[i].penalty=Math.max(0,Number(e.target.value))})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><Chip active={a.enabled} onClick={()=>patch(p=>{p.judging.actions[i].enabled=!p.judging.actions[i].enabled})}>{a.enabled?(ar?'مفعّل':'On'):(ar?'متوقف':'Off')}</Chip><button type="button" onClick={()=>patch(p=>{p.judging.actions=p.judging.actions.filter((_,x)=>x!==i)})} aria-label={ar?'حذف الإجراء':'Remove action'} className="w-11 h-11 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الحد الأدنى للنجاح':'Minimum pass'} value={r.minimumPassingScore} onChange={v=>store.updateRuleSet({minimumPassingScore:v})}/><NumberControl label={ar?'مدة السؤال بالدقائق':'Question minutes'} value={r.questionDurationMinutes} onChange={v=>store.updateRuleSet({questionDurationMinutes:Math.max(1,v)})}/></div><div className="rounded-xl bg-[#E7EEE9] text-[#214C40] p-3 text-xs font-semibold">{ar?'الذكاء الاصطناعي لا يخصم أي درجة. أي إشارة آلية تتحول إلى مراجعة بشرية بعد أن يقفل المحكم تقييمه.':'AI never deducts a score. Any machine observation becomes a human review suggestion only after judges lock.'}</div></div>;
};

const AppealsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'سياسة الاعتراض':'Appeals policy'} subtitle={ar?'كل مسابقة تقرر هل يوجد اعتراض، مدته، أسبابه، ومن يراجعه.':'Each competition decides whether appeals exist, their window, grounds and reviewer.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.appeals.enabled} onChange={v=>patch(p=>{p.appeals.enabled=v})} label={ar?'الاعتراضات مفعلة':'Appeals enabled'}/><Toggle value={policy.appeals.allowScoreChange} onChange={v=>patch(p=>{p.appeals.allowScoreChange=v})} label={ar?'يمكن أن ينتج تعديل درجة بعد قرار بشري':'Human appeal decision may change score'}/></div>{policy.appeals.enabled&&<div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'النافذة بالساعات':'Window hours'} value={policy.appeals.windowHours} onChange={v=>patch(p=>{p.appeals.windowHours=Math.max(1,v)})}/><Control label={ar?'المراجع':'Reviewer'}><TinySelect value={policy.appeals.reviewerRole} onChange={v=>patch(p=>{p.appeals.reviewerRole=v as any})}><option value="head_judge">{ar?'رئيس التحكيم':'Head Judge'}</option><option value="committee">{ar?'اللجنة':'Committee'}</option></TinySelect></Control></div>}<div><div className="text-xs font-black text-[#606662] mb-2">{ar?'الأسباب المسموحة':'Allowed grounds'}</div><div className="flex flex-wrap gap-2">{policy.appeals.grounds.map(g=><Badge key={g} variant="neutral" dot={false}>{uiToken(g,ar)}</Badge>)}</div></div></div>;

const ResultPolicySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'النتائج والاعتماد':'Results & sealing'} subtitle={ar?'النتيجة قد تكون فورية أو خاصة أو مؤجلة للحفل حسب سياسة المسابقة.':'Visibility can be immediate, private, delayed or ceremony-only.'}/><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'الإظهار':'Visibility'}><TinySelect value={policy.results.visibility} onChange={v=>patch(p=>{p.results.visibility=v as any})}><option value="immediate">{ar?'فوري':'Immediate'}</option><option value="after_committee">{ar?'بعد اللجنة':'After committee'}</option><option value="after_round">{ar?'بعد الجولة':'After round'}</option><option value="ceremony_only">{ar?'الحفل فقط':'Ceremony only'}</option><option value="private_only">{ar?'خاص':'Private only'}</option></TinySelect></Control><Control label={ar?'الترتيب العام':'Leaderboard'}><TinySelect value={policy.results.publicLeaderboard} onChange={v=>patch(p=>{p.results.publicLeaderboard=v as any})}><option value="disabled">{ar?'متوقف':'Disabled'}</option><option value="top_only">{ar?'الأوائل فقط':'Top only'}</option><option value="full">{ar?'كامل':'Full'}</option></TinySelect></Control><Control label={ar?'التأهل':'Qualification'}><TinySelect value={policy.results.qualificationRule} onChange={v=>patch(p=>{p.results.qualificationRule=v as any})}><option value="top_n">{ar?'أعلى عدد محدد':'Top N'}</option><option value="minimum_score">{ar?'حد أدنى':'Minimum score'}</option><option value="custom">{ar?'مخصص':'Custom'}</option></TinySelect></Control><NumberControl label={ar?'قيمة التأهل':'Qualification value'} value={policy.results.qualificationValue} onChange={v=>patch(p=>{p.results.qualificationValue=v})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.results.requireDualApprovalToSeal} onChange={v=>patch(p=>{p.results.requireDualApprovalToSeal=v})} label={ar?'اعتمادان مستقلان قبل الختم':'Two independent approvals before seal'}/></div><div><div className="text-xs font-black text-[#606662] mb-2">{ar?'قواعد كسر التعادل':'Tie-break order'}</div><div className="flex flex-wrap gap-2">{policy.results.tieBreakRules.map((x,i)=><Badge key={`${x}-${i}`} variant="neutral" dot={false}>{i+1}. {uiToken(x,ar)}</Badge>)}</div></div></div>;

const CertificateSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const cp=policy.certificates;const brand=store.organization.brand;const title=ar?(cp.titleArabic||'شهادة'):(cp.titleEnglish||'Certificate');const award=ar?(cp.awardTextArabic||''):(cp.awardTextEnglish||'');const orgName=ar?(brand.displayNameArabic||brand.nameArabic):(brand.displayName||brand.name);const competitionName=ar?store.competition.nameArabic:store.competition.name;const verifyLink=`${typeof window!=='undefined'?window.location.origin:''}/#verify`;
 return <div className="space-y-5"><SectionTitle title={ar?'الشهادة':'Certificate'} subtitle={ar?'صمّم محتوى شهادة هادئة ورسمية، ثم يضيف ميزان التحقق الرقمي من دون أكواد تقنية مشوشة.':'Compose a calm official certificate; MIZAN adds digital verification without exposing technical noise.'}/><div className="grid xl:grid-cols-[1fr_.85fr] gap-5 items-start"><div className="space-y-4"><div className="mizan-surface-soft px-4"><Toggle value={cp.enabled} onChange={v=>patch(p=>{p.certificates.enabled=v})} label={ar?'الشهادات مفعلة':'Certificates enabled'}/><Toggle value={cp.autoIssue} onChange={v=>patch(p=>{p.certificates.autoIssue=v})} label={ar?'إصدار تلقائي بعد الإغلاق':'Auto issue after finalization'}/><Toggle value={cp.publicVerification} onChange={v=>patch(p=>{p.certificates.publicVerification=v})} label={ar?'التحقق العام مفعّل':'Public verification enabled'}/><Toggle value={cp.showScore} onChange={v=>patch(p=>{p.certificates.showScore=v})} label={ar?'إظهار الدرجة':'Show score'}/><Toggle value={cp.showRank} onChange={v=>patch(p=>{p.certificates.showRank=v})} label={ar?'إظهار الترتيب':'Show rank'}/></div><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'من يستلم':'Issue for'}><TinySelect value={cp.issueFor} onChange={v=>patch(p=>{p.certificates.issueFor=v as any})}><option value="all_participants">{ar?'كل المشاركين':'All participants'}</option><option value="qualified">{ar?'المتأهلون':'Qualified'}</option><option value="winners">{ar?'الفائزون':'Winners'}</option><option value="custom">{ar?'حسب قاعدة المسابقة':'Competition rule'}</option></TinySelect></Control><TextControl label={ar?'عنوان الشهادة':'Certificate title'} value={title} onChange={v=>patch(p=>{if(ar)p.certificates.titleArabic=v;else p.certificates.titleEnglish=v})}/></div><Control label={ar?'نص الاستحقاق':'Award text'}><textarea value={award} onChange={e=>patch(p=>{if(ar)p.certificates.awardTextArabic=e.target.value;else p.certificates.awardTextEnglish=e.target.value})} className="w-full min-h-28 rounded-xl border border-[#dcdad2] bg-white px-3 py-3 text-sm resize-none"/></Control><div><div className="flex items-center justify-between"><div><div className="text-xs font-black text-[#606662]">{ar?'التوقيعات':'Signatories'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'تظهر كمساحات توقيع نظيفة في أسفل الشهادة.':'Rendered as clean signature blocks at the certificate foot.'}</div></div><button type="button" onClick={()=>patch(p=>{p.certificates.signatories=[...(p.certificates.signatories||[]),{name:'',title:''}]})} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'موقّع':'Signatory'}</button></div><div className="divide-y divide-[#e5e3dc] mt-2">{(cp.signatories||[]).map((s,i)=><div key={i} className="py-3 grid grid-cols-[1fr_1fr_auto] gap-2"><input placeholder={ar?'الاسم':'Name'} value={s.name} onChange={e=>patch(p=>{p.certificates.signatories![i].name=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm"/><input placeholder={ar?'الصفة':'Title'} value={s.title} onChange={e=>patch(p=>{p.certificates.signatories![i].title=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm"/><button type="button" onClick={()=>patch(p=>{p.certificates.signatories=p.certificates.signatories?.filter((_,x)=>x!==i)})} aria-label={ar?'حذف الموقّع':'Remove signatory'} className="w-11 h-11 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div></div><aside className="sticky top-24"><div className="rounded-[26px] border border-[#d8cfbf] bg-[#fffdf8] p-5 sm:p-7 shadow-[0_16px_45px_rgba(66,54,35,.08)] text-center overflow-hidden relative"><div className="absolute inset-x-7 top-4 h-px bg-[#c9b58f]"/><div className="absolute inset-x-7 bottom-4 h-px bg-[#c9b58f]"/><div className="text-[9px] font-black tracking-[.22em] text-[#9B7542]">{ar?'وثيقة رسمية':'OFFICIAL DOCUMENT'}</div>{brand.logoUrl?<img src={brand.logoUrl} alt="" className="w-14 h-14 object-contain mx-auto mt-5"/>:<Award className="w-11 h-11 text-[#9B7542] mx-auto mt-5"/>}<div className="text-[11px] font-bold text-[#646965] mt-3">{orgName}</div><div className="text-[10px] text-[#656b66] mt-1">{competitionName}</div><h3 className="text-2xl font-black mt-6 text-[#202622]">{title}</h3><div className="mt-5 text-[10px] text-[#656b66]">{ar?'تُمنح إلى':'Presented to'}</div><div className="mt-1 text-xl font-black text-[#214C40]">{ar?'اسم المتسابق':'Participant Name'}</div><p className="mt-5 mx-auto max-w-md text-xs leading-6 text-[#4e5551]">{award||(ar?'يظهر هنا نص الاستحقاق الذي كتبته للمسابقة.':'Your award text appears here.')}</p>{(cp.showScore||cp.showRank)&&<div className="mt-5 flex justify-center gap-2">{cp.showScore&&<Badge variant="neutral" dot={false}>{ar?'الدرجة ٩٦٫٥':'Score 96.5'}</Badge>}{cp.showRank&&<Badge variant="emerald" dot={false}>{ar?'المركز الأول':'1st place'}</Badge>}</div>}<div className="mt-8 grid grid-cols-2 gap-5">{(cp.signatories||[]).slice(0,2).map((s,i)=><div key={i} className="border-t border-[#cfc8bb] pt-2 min-h-10"><div className="text-[10px] font-bold">{s.name||(ar?'اسم الموقّع':'Signatory')}</div><div className="text-[9px] text-[#656b66]">{s.title||(ar?'الصفة':'Title')}</div></div>)}</div>{cp.publicVerification&&<div className="mt-7 pt-4 border-t border-[#e3ded3] flex items-center justify-between gap-4 text-start"><div><div className="flex items-center gap-1 text-[10px] font-black text-[#214C40]"><ShieldCheck className="w-3.5 h-3.5"/>{ar?'قابلة للتحقق رقميًا':'Digitally verifiable'}</div><div className="text-[9px] text-[#656b66] mt-1">{ar?'امسح الرمز للتحقق من أصالة الشهادة':'Scan to verify certificate authenticity'}</div></div><div className="bg-white p-1.5 rounded-lg border border-[#e3ded3]"><RealQRCode value={verifyLink} size={54}/></div></div>}</div><div className="mt-2 text-center text-[9px] text-[#656b66]">{ar?'المعاينة تتحدث فورًا ولا تصدر شهادة حقيقية.':'Live preview only; no certificate is issued from this panel.'}</div></aside></div></div>;
};

const PrivacySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'الخصوصية والاحتفاظ':'Privacy & retention'} subtitle={ar?'لا توجد سياسة احتفاظ واحدة لكل الجهات؛ هذه القيم تخص المسابقة الحالية.':'Retention is competition-specific and should match the organization’s legal policy.'}/><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الصوت — أيام':'Audio days'} value={policy.privacy.audioRetentionDays} onChange={v=>patch(p=>{p.privacy.audioRetentionDays=Math.max(0,v)})}/><NumberControl label={ar?'المستندات — أيام':'Document days'} value={policy.privacy.documentRetentionDays} onChange={v=>patch(p=>{p.privacy.documentRetentionDays=Math.max(0,v)})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.privacy.allowAiProcessing} onChange={v=>patch(p=>{p.privacy.allowAiProcessing=v})} label={ar?'السماح بالمساندة الآلية':'Allow assistive AI processing'}/><Toggle value={policy.privacy.displayParticipantNameOnPublicScreens} onChange={v=>patch(p=>{p.privacy.displayParticipantNameOnPublicScreens=v})} label={ar?'إظهار الاسم على الشاشات العامة':'Show participant names publicly'}/><Toggle value={policy.privacy.allowAnonymousBenchmarking} onChange={v=>patch(p=>{p.privacy.allowAnonymousBenchmarking=v})} label={ar?'مقارنات مجهولة الهوية':'Anonymous benchmarking'}/></div></div>;

const ParticipantsView=({store,ar,query,setQuery,filtered}:{store:Store;ar:boolean;query:string;setQuery:(s:string)=>void;filtered:Store['participants']})=><div className="space-y-4"><div className="flex items-end justify-between gap-4"><div><div className="mizan-kicker">{ar?'المتسابقون':'PARTICIPANTS'}</div><h1 className="text-3xl font-black mt-1">{store.participants.length}</h1></div><div className="flex items-center gap-2">{(()=>{const pend=store.participants.filter(p=>p.status==='submitted'||p.status==='under_review');return pend.length>0?<Button size="sm" variant="secondary" onClick={()=>{if(typeof window!=='undefined'&&!window.confirm(ar?`اعتماد ${pend.length} طلبًا معلّقًا؟`:`Approve ${pend.length} pending applications?`))return;pend.forEach(p=>store.reviewParticipant(p.id,'approved'))}}>{ar?`اعتماد الكل (${pend.length})`:`Approve all (${pend.length})`}</Button>:null})()}<div className="relative w-full max-w-xs"><Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#686e6a]"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={ar?'اسم أو كود':'Name or code'} className="w-full rounded-xl border border-[#dcdad2] bg-white ps-10 pe-3 py-2.5 text-sm"/></div></div></div><div className="mizan-surface overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{filtered.map(p=>{const cat=store.competition.categories.find(c=>c.id===p.categoryId);const needs=p.status==='submitted'||p.status==='under_review';return <div key={p.id} className="p-4 sm:px-5 flex items-center gap-4"><div className="w-11 h-11 rounded-xl bg-[#E7EEE9] text-[#214C40] grid place-items-center font-black text-xs">{p.code.replace('A-','')}</div><div className="min-w-0 flex-1"><div className="font-bold text-sm truncate">{ar?p.fullNameArabic:p.fullName}</div><div className="text-[11px] text-[#656b66] mt-1 truncate">{ar?cat?.nameArabic:cat?.name} · {p.country||'—'}</div></div><Badge variant={p.status==='in_queue'?'amber':p.status==='tested'||p.status==='certified'?'emerald':'neutral'}>{statusLabel(p.status,ar)}</Badge>{needs&&<div className="flex gap-1"><Button size="sm" variant="secondary" onClick={()=>store.reviewParticipant(p.id,'approved')}>{ar?'اعتماد':'Approve'}</Button><Button size="sm" variant="ghost" onClick={()=>store.reviewParticipant(p.id,'rejected')}>{ar?'رفض':'Reject'}</Button></div>}</div>})}</div></div></div>;

const committeeAutoStatus=(c:Store['committees'][number],requiredJudges:number):'ready'|'testing'|'paused'|'offline'=>{if(c.status==='paused')return 'paused';if(c.devicesConnected<=0&&!c.audioInputOk)return 'offline';if(!c.audioInputOk||c.devicesConnected<=0||c.judgeIds.length<Math.max(1,requiredJudges)||!c.headJudgeId)return 'testing';return 'ready'};
const committeeStatusLabel=(status:'ready'|'testing'|'paused'|'offline',ar:boolean)=>status==='ready'?(ar?'جاهزة':'Ready'):status==='testing'?(ar?'جارٍ التحقق':'Checking'):status==='paused'?(ar?'متوقفة مؤقتًا':'Paused'):(ar?'غير متصلة':'Offline');

const OperationsView=({store,ar,sim,simCount,setSimCount,attention}:{store:Store;ar:boolean;sim:any;simCount:number;setSimCount:(n:number)=>void;attention:any[]})=><div className="space-y-4">{(store.continuityIncidents.some(x=>x.status!=='RESOLVED')||store.sessionRecoveries.some(x=>x.status==='PROPOSED'&&x.decision==='FULL_RETEST_LAST_RESORT'))&&<ContinuityRecovery/>}<div className="flex items-end justify-between"><div><div className="mizan-kicker">{ar?'التشغيل الذكي':'MIZAN AUTOPILOT'}</div><h1 className="text-3xl font-black mt-1">{ar?'شغّل بالاستثناء':'Operate by exception'}</h1></div><Button size="sm" variant="outline" onClick={()=>store.addCommittee()} icon={<Plus className="w-4 h-4"/>}>{ar?'لجنة':'Panel'}</Button></div><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3">{store.committees.map(c=><div key={c.id} className="mizan-surface p-4 min-w-0"><div className="flex items-start justify-between gap-3"><Badge variant={committeeAutoStatus(c,store.competition.ruleSet.judgesCountPerPanel)==='offline'?'rose':committeeAutoStatus(c,store.competition.ruleSet.judgesCountPerPanel)==='testing'?'blue':committeeAutoStatus(c,store.competition.ruleSet.judgesCountPerPanel)==='paused'?'amber':'emerald'}>{c.code}</Badge><div className="text-end"><div className="text-[9px] font-black text-[#656b66]">{ar?'حالة اللجنة — تلقائية':'Panel status — automatic'}</div><div className="mt-1 text-xs font-black">{committeeStatusLabel(committeeAutoStatus(c,store.competition.ruleSet.judgesCountPerPanel),ar)}</div></div></div><input value={ar?c.nameArabic:c.name} onChange={e=>store.updateCommittee(c.id,ar?{nameArabic:e.target.value}:{name:e.target.value})} className="w-full bg-transparent border-0 p-0 font-bold text-sm mt-4 outline-none"/><div className="mt-3 flex items-center justify-between"><span className="text-xs text-[#656b66]">{c.completedCount} {ar?'مكتمل':'done'}</span><label className="text-[10px] text-[#656b66] flex items-center gap-1" title={ar?'متوسط زمن الجلسة للمتسابق الواحد بالدقائق':'Average session minutes per participant'}><Clock3 className="w-3 h-3"/><span>{ar?'متوسط الجلسة (دقيقة)':'min/session'}</span><input type="number" step="0.1" aria-label={ar?'متوسط دقائق الجلسة':'Average session minutes'} value={c.averageSessionMinutes} onChange={e=>store.updateCommittee(c.id,{averageSessionMinutes:Number(e.target.value)})} className="w-12 bg-transparent border-b border-[#ddd] text-end"/></label></div></div>)}</div><div className="grid xl:grid-cols-[1fr_.55fr] gap-4"><div className="mizan-surface p-5"><div className="flex items-center justify-between mb-5"><div><div className="mizan-kicker">{ar?'محاكاة السعة':'DIGITAL TWIN'}</div><h2 className="font-extrabold mt-1">{ar?'اختبر السعة قبل اليوم الحقيقي':'Test capacity before event day'}</h2></div><div className="flex items-center gap-2"><Button size="sm" variant="outline" onClick={()=>store.optimizeArrivalSlots()}>{ar?'تحسين الوصول':'Optimize arrivals'}</Button><input type="number" min={1} max={40} value={simCount} onChange={e=>setSimCount(Number(e.target.value))} className="w-16 rounded-xl border border-[#ddd] px-2 py-2 text-center text-sm font-bold"/></div></div><div className="grid grid-cols-3 gap-3"><MiniMetric value={sim.projectedFinishTime} label={ar?'انتهاء':'Finish'}/><MiniMetric value={`${sim.averageWaitMinutes}${ar?' د':'m'}`} label={ar?'انتظار':'Wait'}/><MiniMetric value={`${sim.maxWaitMinutes}${ar?' د':'m'}`} label={ar?'أقصى':'Max'}/></div><div className="mt-4 rounded-xl bg-[#E7EEE9] p-3 text-xs font-semibold text-[#214C40]">{ar?sim.optimizationAdviceArabic:sim.optimizationAdviceEnglish}</div></div><div className="mizan-surface p-5"><div className="mizan-kicker">{ar?'الحالات الاستثنائية':'EXCEPTIONS'}</div><div className="mt-4 space-y-2">{attention.filter(x=>x.kind!=='setup').length?attention.filter(x=>x.kind!=='setup').map(x=><div key={x.id} className="flex items-start gap-2 text-xs font-semibold"><CircleAlert className="w-4 h-4 text-[#89673a] shrink-0"/>{x.title}</div>):<div className="text-center py-8 text-xs text-[#656b66]"><BadgeCheck className="w-6 h-6 text-[#2F6555] mx-auto mb-2"/>{ar?'لا توجد حالات':'No active exceptions'}</div>}</div></div></div></div>;

const ResultsView=({store,ar}:{store:Store;ar:boolean})=>{const policy=getCompetitionPolicy(store.competition);
 /* الختم قد يُرفض لسبب لا يعرفه من ضغط الزر — فيُقال، ولا يُترك الزر يبتلع الرفض. */
 const [sealNote,setSealNote]=useState('');
 const sealNow=async()=>{const out=await store.sealResults();setSealNote(out?.sealed?'':String((out as {message?:string})?.message||''))}; const pending=store.appeals.filter(a=>a.status==='submitted'||a.status==='under_review').length; const allSealed=store.results.length>0&&store.results.every(r=>r.status==='sealed'||r.status==='published');return <div className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mizan-kicker">{ar?'النتائج':'RESULTS'}</div><h1 className="text-3xl font-black mt-1">{ar?'اعتماد، ختم، نشر':'Approve · seal · publish'}</h1><p className="text-sm text-[#636965] mt-2">{ar?`الإظهار: ${uiToken(policy.results.visibility,true)}`:`Visibility: ${uiToken(policy.results.visibility,false)}`}</p></div><div className="flex gap-2"><Button variant="outline" onClick={()=>void sealNow()} icon={<LockKeyhole className="w-4 h-4"/>}>{policy.results.requireDualApprovalToSeal?<>{ar?'اعتماد الختم ':'Seal approval '}<Ratio value={new Set(store.sealApprovals.map(a=>a.actorId)).size} of={2}/></>:(ar?'ختم':'Seal')}</Button><Button disabled={!allSealed} onClick={()=>store.publishResults()}>{ar?'نشر':'Publish'}</Button></div></div>{sealNote&&<div role="status" className="rounded-xl bg-[#F5EDE2] text-[#7a5a2f] p-3 text-xs font-bold leading-5">{sealNote}</div>}{pending>0&&<div className="rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs font-bold">{ar?`${pending} اعتراضات تحتاج حسمًا قبل الإغلاق`:`${pending} appeals require resolution before closure`}</div>}<div className="mizan-surface overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{[...store.results].sort((a,b)=>a.rank-b.rank).map(r=><div key={r.id} className="p-4 sm:px-5 flex items-center gap-4"><div className="w-10 text-2xl font-black text-[#214C40]">{r.rank||'—'}</div><div className="min-w-0 flex-1"><div className="font-bold text-sm truncate">{ar?r.participantNameArabic:r.participantName}</div><div className="text-[11px] text-[#656b66] mt-1">{r.categoryName} · {localizedCountry(r.country,ar)}</div></div><div className="font-black tabular-nums">{r.finalScore.toFixed(2)}</div><Badge variant={r.status==='sealed'||r.status==='published'?'emerald':'neutral'}>{uiToken(r.status,ar)}</Badge><button disabled={!['sealed','published'].includes(r.status)} onClick={()=>store.generateCertificate(r.id)} title={ar?'إصدار شهادة':'Issue certificate'} aria-label={ar?'إصدار شهادة':'Issue certificate'} className="w-11 h-11 rounded-xl grid place-items-center hover:bg-[#efede7] text-[#59615c] disabled:opacity-30"><Award className="w-4 h-4"/></button></div>)}</div></div><div className="text-xs text-[#656b66]">{store.certificates.length} {ar?'شهادة':'certificates'} · {store.auditLogs.length} {ar?'حدث تدقيق':'audit events'}</div></div>};

const RegistrationFieldRow=({f,ar,onVisible,onRequired}:{f:RegistrationFieldDefinition;ar:boolean;onVisible:(v:boolean)=>void;onRequired:(v:boolean)=>void})=><div className="py-3 grid grid-cols-[1fr_auto] items-center gap-3"><div><div className="text-sm font-bold">{ar?f.labelArabic:f.labelEnglish}</div><div className="text-[11px] text-[#666b67]">{f.type}</div></div><div className="flex gap-1"><Chip active={f.visible} onClick={()=>onVisible(!f.visible)}>{f.visible?(ar?'ظاهر':'Visible'):(ar?'مخفي':'Hidden')}</Chip><Chip active={f.required} amber onClick={()=>onRequired(!f.required)}>{f.required?(ar?'إلزامي':'Required'):(ar?'اختياري':'Optional')}</Chip></div></div>;
const Toggle=({value,onChange,label}:{value:boolean;onChange:(v:boolean)=>void;label:string})=><button type="button" onClick={()=>onChange(!value)} className="w-full flex items-center justify-between gap-4 py-3 text-start border-b border-[#e7e5de] last:border-0"><span className="text-sm font-semibold text-[#303733]">{label}</span><span className={`relative w-10 h-6 rounded-full transition ${value?'bg-[#214C40]':'bg-[#d6d4cd]'}`}><span className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow-sm transition ${value?'end-1':'end-5'}`}/></span></button>;
const Chip=({active=false,amber=false,onClick,children}:{active?:boolean;amber?:boolean;onClick:()=>void;children:React.ReactNode})=><button type="button" onClick={onClick} className={`px-2.5 py-1.5 rounded-lg text-[11px] font-bold ${active?(amber?'bg-[#F2EADC] text-[#7d5e34]':'bg-[#E7EEE9] text-[#214C40]'):'bg-[#efede7] text-[#777]'}`}>{children}</button>;
const NavButton=({active,onClick,icon:Icon,label}:{active:boolean;onClick:()=>void;icon:React.ComponentType<{className?:string}>;label:string})=><button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold transition ${active?'bg-[#214C40] text-white':'text-[#626a65] hover:bg-[#efede7] hover:text-[#303733]'}`}><Icon className="w-4 h-4"/><span>{label}</span></button>;
const TinySelect=({value,onChange,children}:{value:string;onChange:(v:string)=>void;children:React.ReactNode})=><select value={value} onChange={e=>onChange(e.target.value)} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold text-[#303733]">{children}</select>;
const SectionTitle=({title,subtitle}:{title:string;subtitle:string})=><div><h2 className="text-xl font-black text-[#202622]">{title}</h2><p className="text-xs text-[#646965] mt-1.5 max-w-2xl">{subtitle}</p></div>;
const Control=({label,children}:{label:string;children:React.ReactNode})=><label className="block"><span className="block text-xs font-black text-[#686f6a] mb-2">{label}</span>{children}</label>;
const TextControl=({label,value,onChange,type='text'}:{label:string;value:string;onChange:(v:string)=>void;type?:string})=><Control label={label}><input type={type} value={value} onChange={e=>onChange(e.target.value)} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold"/></Control>;
const NumberControl=({label,value,onChange,step=1}:{label:string;value:number;onChange:(v:number)=>void;step?:number})=><Control label={label}><input type="number" step={step} value={value} onChange={e=>onChange(Number(e.target.value))} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold"/></Control>;
const MetricCard=({icon:Icon,value,label}:{icon:React.ComponentType<{className?:string}>;value:number|string;label:string})=><div className="mizan-surface p-4 sm:p-5 min-w-0"><Icon className="w-4 h-4 text-[#2F6555] mb-4"/><div className="text-2xl sm:text-3xl font-black truncate">{value}</div><div className="text-xs text-[#636864] mt-1 truncate">{label}</div></div>;
const MiniMetric=({value,label}:{value:string;label:string})=><div className="rounded-xl bg-[#f1efe9] p-4"><div className="text-xl font-black">{value}</div><div className="text-[11px] text-[#636965] mt-1">{label}</div></div>;
const workflowLabel=(id:string,ar:boolean)=>({register:ar?'التسجيل':'Register',verify:ar?'التحقق':'Verify',approve:ar?'الاعتماد':'Approve',schedule:ar?'الجدولة':'Schedule',notify:ar?'الإشعار':'Notify',checkin:ar?'الحضور':'Check-in',route:ar?'التوجيه':'Route',draw:ar?'السحب':'Draw',judge:ar?'التحكيم':'Judge',integrity:ar?'النزاهة':'Integrity',seal:ar?'الختم':'Seal',publish:ar?'النشر':'Publish',certificate:ar?'الشهادة':'Certificate'} as Record<string,string>)[id]||id;
const statusLabel=(s:string,ar:boolean)=>({submitted:ar?'مرسل':'Submitted',under_review:ar?'مراجعة':'Review',approved:ar?'مقبول':'Approved',checked_in:ar?'حضر':'Checked in',in_queue:ar?'ينتظر':'Waiting',in_session:ar?'داخل اللجنة':'In session',tested:ar?'اختبر':'Tested',appealed:ar?'اعتراض':'Appeal',certified:ar?'معتمد':'Certified',draft:ar?'مسودة':'Draft',rejected:ar?'مرفوض':'Rejected'} as Record<string,string>)[s]||s;
